const KEY='setmate-v1';
const initial={person:'Justin',unit:'lb',machines:[{id:'leg-press',name:'Seated leg press',group:'Legs'},{id:'chest-press',name:'Chest press',group:'Chest'},{id:'lat-pulldown',name:'Lat pulldown',group:'Back'},{id:'seated-row',name:'Seated row',group:'Back'},{id:'shoulder-press',name:'Shoulder press',group:'Shoulders'},{id:'leg-curl',name:'Seated leg curl',group:'Legs'}],sets:[]};
let state,storageError='';try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(initial);if(!Array.isArray(state.machines)||!Array.isArray(state.sets))throw Error('Invalid saved data');}catch(e){state=structuredClone(initial);storageError='Your saved data could not be loaded. Please keep this window open; saving is disabled to protect any existing data.';}
if(!storageError){const migrated={...state,person:state.person==='You'?'Justin':state.person,machines:state.machines.map(m=>({...m,name:m.id==='leg-press'&&m.name==='Leg press'?'Seated leg press':m.id==='leg-curl'&&m.name==='Leg curl'?'Seated leg curl':m.name,brand:m.brand||'Other'})),sets:state.sets.map(s=>({...s,person:s.person==='You'?'Justin':s.person}))};try{localStorage.setItem(KEY,JSON.stringify(migrated));state=migrated;}catch(e){storageError='Could not update local storage. Your existing records have been preserved.';}}
let brand='All',showHidden=false;
let view='list',selected=null,query='',group='All',weight='',reps='',offlineReady=false;
const root=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDay=t=>{const d=new Date(t);return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;};
const isToday=t=>localDay(t)===localDay(Date.now());
function save(next){if(storageError){toast('Storage unavailable. Your set was not saved.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('Could not save. Check your device storage and try again.');return false;}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function machineSets(){return state.sets.filter(s=>s.machine===selected&&s.person===state.person);}
function format(s){return `${s.weight} ${s.unit}${s.reps!=null?' × '+s.reps+' reps':''}`;}
function dateLabel(t){if(isToday(t))return 'Today';return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:new Date(t).getFullYear()!==new Date().getFullYear()?'numeric':undefined});}
function header(){return `<header><div class="brand"><span class="mark" aria-hidden="true">Ⅱ</span>setmate<span style="color:var(--lime)">.</span></div><button class="icon-button" data-action="info" aria-label="App and installation information">ⓘ</button></header>`;}
function people(){return `<div class="people" aria-label="Workout profile">${['Justin','Mabel'].map(p=>`<button data-person="${p}" class="${state.person===p?'active':''}" aria-pressed="${state.person===p}"><img class="panda" src="panda-${p.toLowerCase()}.png" alt="">${p}</button>`).join('')}</div>`;}
function footer(){return `<div class="foot"><span class="dot"></span><span>${offlineReady?'Ready offline · Saved on this device':'Saved on this device'}</span></div>`;}
function render(){if(view==='list')renderList();else if(view==='detail')renderDetail();else if(view==='add')renderAdd();else renderInfo();}
function listMarkup(){const filtered=state.machines.filter(m=>(showHidden||!m.hidden)&&(group==='All'||m.group===group)&&(brand==='All'||(m.brand||'Other')===brand)&&m.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>lastUsed(a)-lastUsed(b)||a.name.localeCompare(b.name));return `<div class="section-row"><h2>Your machines</h2><span class="count">${filtered.length} machines</span></div><p class="hint" style="margin:0 0 15px">Longest since last use first · ${esc(state.person)}</p><div class="machine-list">${filtered.map(m=>{const last=state.sets.filter(s=>s.machine===m.id&&s.person===state.person).sort((a,b)=>a.time.localeCompare(b.time)).at(-1);return `<button class="machine" data-machine="${esc(m.id)}"><span class="machine-code" aria-hidden="true">${esc(m.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span><span class="machine-content"><strong>${esc(m.name)} ${m.hidden?'<span class="brand-tag">Hidden</span>':''} ${m.brand==='HOIST'?'<span class="brand-tag">HOIST</span>':''}</strong><small>${last?esc(format(last))+' · '+esc(dateLabel(last.time)):esc(m.group)+' · No sets yet'}</small></span><span class="chevron" aria-hidden="true">›</span></button>`;}).join('')||'<div class="empty">No machines found.<br>Try another filter or add a machine.</div>'}</div>`;}
function renderList(){root.innerHTML=header()+`<div class="eyebrow">Your workout, at a glance</div><h1>Let’s get a set in.</h1>`+people()+`${storageError?`<p class="error">${esc(storageError)}</p>`:''}<div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Find a machine" aria-label="Filter machines by name" value="${esc(query)}"></div><div class="chips" aria-label="Filter by muscle group">${['All',...new Set(state.machines.map(m=>m.group))].map(g=>`<button data-group="${esc(g)}" class="${group===g?'active':''}" aria-pressed="${group===g}">${esc(g)}</button>`).join('')}</div><div class="brand-filter" aria-label="Filter by machine type">${['All','HOIST','Other'].map(b=>`<button data-brand="${b}" class="${brand===b?'active':''}" aria-pressed="${brand===b}">${b==='Other'?'Other machines':b==='All'?'All machines':b}</button>`).join('')}</div><button class="hidden-toggle" data-action="toggle-hidden" aria-pressed="${showHidden}">${showHidden?'Hide hidden machines':'Show hidden machines'}</button><div id="list-results">${listMarkup()}</div><button class="add" data-action="add">＋ Add a machine</button>`+footer();}
function renderDetail(){const m=state.machines.find(m=>m.id===selected);const sets=machineSets().sort((a,b)=>a.time.localeCompare(b.time));const today=sets.filter(s=>isToday(s.time));const previous=sets.filter(s=>!isToday(s.time));const last=previous.at(-1);const lastSets=last?previous.filter(s=>localDay(s.time)===localDay(last.time)):[];root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">${esc(m.group)}${m.brand==='HOIST'?' · HOIST':''}</div><h1>${esc(m.name)}</h1>`+people()+`<div class="last"><div class="last-label"><strong>Last workout · ${esc(state.person)}</strong><span>${last?esc(dateLabel(last.time)):''}</span></div>${last?`<div class="last-sets">${lastSets.map(s=>`<button data-repeat="${s.id}" aria-label="Use ${esc(format(s))}">${esc(format(s))}</button>`).join('')}</div><p class="hint">Tap a set to use those numbers again.</p>`:`<p class="sub" style="margin:0">No previous workout yet. Your first set starts here.</p>`}</div><form id="set-form"><div class="entry"><div class="label-row"><label for="weight">Weight</label><div class="units">${['lb','kg'].map(u=>`<button type="button" data-unit="${u}" class="${state.unit===u?'active':''}" aria-pressed="${state.unit===u}">${u}</button>`).join('')}</div></div><div class="stepper"><button type="button" data-step="weight:-5" aria-label="Decrease weight">−</button><input id="weight" name="weight" type="text" inputmode="decimal" placeholder="0" autocomplete="off" aria-label="Weight in ${state.unit}" value="${esc(weight)}" required><button type="button" data-step="weight:5" aria-label="Increase weight">＋</button></div><div class="suggestions">${suggestions(m).map(w=>`<button type="button" data-weight="${w}">${w} ${state.unit}</button>`).join('')}</div><p class="hint">${m.brand==='HOIST'?'Suggestions use recorded HOIST weights. Check the machine’s label.':'Suggested from your recent sets.'} Tap the number above to enter any custom weight.</p></div><div class="entry"><div class="label-row"><label for="reps">Reps <span class="optional">optional</span></label><button type="button" class="undo" data-action="clear-reps">Clear</button></div><div class="stepper"><button type="button" data-step="reps:-1" aria-label="Decrease reps by 1">−</button><input id="reps" name="reps" type="text" inputmode="numeric" placeholder="—" autocomplete="off" aria-label="Reps, optional" value="${esc(reps)}"><button type="button" data-step="reps:1" aria-label="Increase reps by 1">＋</button></div></div><button class="primary" type="submit">＋ Log set for ${esc(state.person)}</button></form><section class="today"><div class="section-row"><h2>Today’s sets</h2><span class="count">${today.length} ${today.length===1?'set':'sets'}</span></div>${today.map((s,i)=>`<div class="set-row"><span class="set-num">${String(i+1).padStart(2,'0')}</span><span class="set-detail">${esc(format(s))}<br><small>${new Date(s.time).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</small></span><button class="undo" data-remove="${s.id}" aria-label="Remove set ${i+1}">Remove</button></div>`).join('')||'<p class="sub">No sets logged today. Ready when you are.</p>'}${historyMarkup(sets)}</section><button class="add" data-action="hide-machine">${m.hidden?'Show this machine again':'Hide this machine'}</button>`+footer();}
function renderAdd(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">Make it yours</div><h1>Add a machine.</h1><form id="machine-form" class="form"><label>Machine name<input name="name" placeholder="e.g. Cable row" maxlength="80" required autocomplete="off"></label><label>Machine type<select name="brand"><option>Other</option><option>HOIST</option></select></label><label>Muscle group<select name="group">${['Legs','Chest','Back','Shoulders','Arms','Core','Other'].map(g=>`<option>${g}</option>`).join('')}</select></label><button class="primary" type="submit">Add machine</button></form>`+footer();}
function renderInfo(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">Always in your corner</div><h1>Your pocket log.</h1><div class="notice"><strong>Install on iPhone</strong><ol><li>Open this app’s link in Safari.</li><li>Tap Share, then <strong>Add to Home Screen</strong>.</li><li>Keep <strong>Open as Web App</strong> enabled if shown, then tap Add.</li></ol></div><div class="notice"><strong>Saved here, for you.</strong><p>Machines and sets stay on this device. Justin and Mabel have separate histories. Nothing is sent to a server, and devices don’t sync.</p><p>Clearing website data removes your log. The Home Screen app may have separate storage from Safari and this preview; log real workouts in the installed app.</p><strong>Your notebook</strong><p>Import the notebook file on each device. Records stay here and are never uploaded.</p><label class="import-label">Import workout file<input id="import-file" type="file" accept=".json,application/json"></label><p id="import-status" role="status"></p><p id="offline-info">${offlineReady?'Ready to use offline.':'Loading offline files. Keep the app open until it’s ready.'}</p></div>`+footer();}
function preload(){const last=machineSets().sort((a,b)=>a.time.localeCompare(b.time)).at(-1);weight=last?String(last.weight):'';reps=last&&last.reps!==null?String(last.reps):'';if(last&&last.unit!==state.unit)save({...state,unit:last.unit});}
root.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#list-results').innerHTML=listMarkup();}if(e.target.id==='weight')weight=e.target.value;if(e.target.id==='reps')reps=e.target.value;});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.person){if(save({...state,person:d.person})){if(view==='detail')preload();render();}}else if(d.machine){selected=d.machine;view='detail';preload();render();window.scrollTo(0,0);}else if(d.brand){brand=d.brand;render();}else if(d.weight){weight=d.weight;document.querySelector('#weight').value=weight;}else if(d.group){group=d.group;render();}else if(d.action){if(d.action==='toggle-hidden'){showHidden=!showHidden;render();}if(d.action==='hide-machine'){const m=state.machines.find(x=>x.id===selected);if(save({...state,machines:state.machines.map(x=>x.id===selected?{...x,hidden:!x.hidden}:x)})){view='list';render();toast(m.hidden?'Machine shown again':'Machine hidden. History kept.');}}if(d.action==='back'){view='list';render();window.scrollTo(0,0);}if(d.action==='add'){view='add';render();}if(d.action==='info'){view='info';render();}if(d.action==='clear-reps'){reps='';document.querySelector('#reps').value='';}}else if(d.unit){const next=d.unit;if(next!==state.unit&&weight.trim()!==''&&Number.isFinite(Number(weight))){weight=String(Math.round(Number(weight)*(next==='kg'?0.45359237:2.20462262)*10)/10);}if(save({...state,unit:next}))render();}else if(d.step){const [field,delta]=d.step.split(':');let value=Number(field==='weight'?weight:reps)||0;if(field==='weight'){const m=state.machines.find(m=>m.id===selected);if(m.brand==='HOIST'){const choices=observedWeights(m);value=Number(delta)>0?(choices.find(w=>w>value)??value):(choices.filter(w=>w<value).at(-1)??value);if(!choices.length){toast('Enter the weight shown on this HOIST machine');return;}}else{value=Math.max(0,Math.round((value+Number(delta)*(state.unit==='kg'?0.5:1))*10)/10);}}else value=Math.max(1,value+Number(delta));if(field==='weight')weight=String(value);else reps=String(value);document.querySelector('#'+field).value=value;}else if(d.repeat){const s=state.sets.find(s=>s.id===d.repeat);weight=String(s.weight);reps=s.reps===null?'':String(s.reps);save({...state,unit:s.unit});render();toast('Numbers ready. Tap Log set to save.');}else if(d.remove){if(save({...state,sets:state.sets.filter(s=>s.id!==d.remove)})){render();toast('Set removed');}}});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='machine-form'){const f=new FormData(e.target);const name=f.get('name').trim();if(!name){toast('Enter a machine name');return;}if(state.machines.some(m=>m.name.toLowerCase()===name.toLowerCase()&&(m.brand||'Other')===(f.get('brand')||'Other'))){toast('That machine is already on your list');return;}if(save({...state,machines:[...state.machines,{id:crypto.randomUUID(),name,group:f.get('group'),brand:f.get('brand')||'Other'}]})){view='list';query='';group='All';brand='All';render();toast('Machine added');}}else if(e.target.id==='set-form'){const w=Number(weight.trim().replace(',','.'));const r=reps.trim()===''?null:Number(reps);if(weight.trim()===''||!Number.isFinite(w)||w<0||w>10000){toast('Enter a weight from 0 to 10,000');return;}if(r!==null&&(!Number.isInteger(r)||r<1||r>999)){toast('Enter whole reps from 1 to 999, or leave blank');return;}const s={id:crypto.randomUUID(),machine:selected,person:state.person,weight:w,reps:r,unit:state.unit,time:new Date().toISOString()};if(save({...state,sets:[...state.sets,s]})){weight=String(w);render();toast('Set saved for '+state.person);}}});
function lastUsed(m){const times=state.sets.filter(s=>s.machine===m.id&&s.person===state.person).map(s=>Date.parse(s.time));return times.length?Math.max(...times):0;}
function observedWeights(m){return [...new Set(state.sets.filter(s=>s.machine===m.id).map(s=>Math.round(s.weight*(s.unit===state.unit?1:state.unit==='kg'?0.45359237:2.20462262)*10)/10))].sort((a,b)=>a-b);}
function suggestions(m){const own=machineSets().filter(s=>s.unit===state.unit).sort((a,b)=>a.time.localeCompare(b.time));const recent=own.at(-1);if(m.brand==='HOIST')return observedWeights(m);if(!recent)return [];const step=state.unit==='kg'?2.5:5;return [...new Set([Math.max(0,recent.weight-step),recent.weight,recent.weight+step])];}
function historyMarkup(sets){const old=sets.filter(s=>!isToday(s.time));const days=[...new Set(old.map(s=>localDay(s.time)))].reverse();return days.length?'<details class="history"><summary>Workout history · '+days.length+' days</summary>'+days.map(day=>{const rows=old.filter(s=>localDay(s.time)===day);return '<div class="history-day"><h3>'+esc(dateLabel(rows[0].time))+'</h3>'+rows.map(s=>'<div class="history-set">'+esc(format(s))+(s.transcriptionNote?'<small class="transcription">Notebook estimate: '+esc(s.transcriptionNote)+'</small>':'')+'</div>').join('')+'</div>';}).join('')+'</details>':'';}
function validateImport(data){if(data.version!==1||!Array.isArray(data.machines)||!Array.isArray(data.sets)||data.sets.length>10000||data.machines.length>500)throw Error('This is not a supported workout file.');const ids=new Set();for(const m of data.machines){if(typeof m.id!=='string'||ids.has(m.id)||typeof m.name!=='string'||!m.name.trim()||typeof m.group!=='string'||!['HOIST','Other'].includes(m.brand))throw Error('Invalid machine in workout file.');ids.add(m.id);}const setIds=new Set();for(const s of data.sets){if(typeof s.id!=='string'||setIds.has(s.id)||!ids.has(s.machine)||!['Justin','Mabel'].includes(s.person)||!['lb','kg'].includes(s.unit)||typeof s.weight!=='number'||!Number.isFinite(s.weight)||s.weight<0||s.weight>10000||(s.reps!==null&&(!Number.isInteger(s.reps)||s.reps<1||s.reps>999))||typeof s.time!=='string'||Number.isNaN(Date.parse(s.time)))throw Error('Invalid set in workout file.');setIds.add(s.id);}return data;}
function mergeImport(data){validateImport(data);const machines=[...state.machines],map=new Map();for(const m of data.machines){const existing=machines.find(x=>x.name.toLowerCase()===m.name.toLowerCase()&&(x.brand||'Other')===m.brand);if(existing)map.set(m.id,existing.id);else{const id=machines.some(x=>x.id===m.id)?'notebook-'+m.id:m.id;if(machines.some(x=>x.id===id))throw Error('Machine ID conflict.');machines.push({...m,id});map.set(m.id,id);}}const ids=new Set(state.sets.map(s=>s.id));const incoming=data.sets.filter(s=>!ids.has(s.id)).map(s=>({...s,machine:map.get(s.machine)}));const next={...state,machines,sets:[...state.sets,...incoming].sort((a,b)=>a.time.localeCompare(b.time))};if(!save(next))throw Error('Nothing imported. Local storage is unavailable.');return incoming.length;}
root.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;const file=e.target.files[0];const status=document.querySelector('#import-status');try{if(file.size>3000000)throw Error('File is too large.');const data=JSON.parse(await file.text());const count=mergeImport(data);status.textContent=count+' sets imported. '+(data.omitted?.length?data.omitted.length+' unclear notebook entries were left out.':'');toast(count?'Notebook imported':'Already imported; no duplicates added');}catch(err){status.textContent=err.message;}});

render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js?v=4', {updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;const f=document.querySelector('.foot span:last-child');if(f)f.textContent='Ready offline · Saved on this device';const info=document.querySelector('#offline-info');if(info)info.textContent='Ready to use offline.';}).catch(()=>{const info=document.querySelector('#offline-info');if(info)info.textContent='Offline setup failed. Reopen the app while online to try again.';});}
